import threading

from .errors import InsufficientFunds


class Wallets:
    def __init__(self):
        self._balances: dict[str, int] = {}
        self._lock = threading.Lock()

    def deposit(self, wallet_id: str, cents: int) -> None:
        with self._lock:
            self._balances[wallet_id] = self._balances.get(wallet_id, 0) + cents

    def balance(self, wallet_id: str) -> int:
        with self._lock:
            return self._balances.get(wallet_id, 0)

    def withdraw(self, wallet_id: str, cents: int) -> None:
        """Take `cents` out; called from the request threads."""
        if self.balance(wallet_id) < cents:
            raise InsufficientFunds(wallet_id)
        with self._lock:
            self._balances[wallet_id] -= cents
